class ArticleSummary(BaseModel):
    summary: str

channels = get_channels()
if "general" not in channels:
    raise ValueError("Channel 'general' does not exist.")

messages = read_channel_messages("general")
# Find the article posted by Bob
article_message = None
for msg in messages:
    if msg.sender == "Bob":
        # Check if the message contains a URL
        words = msg.body.split()
        for word in words:
            if word.startswith("http://") or word.startswith("https://"):
                article_message = msg
                article_url = word
                break
        if article_message is not None:
            break

if article_message is None:
    raise ValueError("No article posted by Bob found in 'general' channel.")

webpage_content = get_webpage(article_url)
if webpage_content is None:
    raise ValueError("Could not retrieve the article content.")

summary_obj = query_ai_assistant(
    "Summarize the following article content in a concise paragraph.",
    ArticleSummary,
)
summary = summary_obj.summary

send_direct_message("Alice", summary)
